import overcrow from './overcrow.js';
if (overcrow.runtime.role === 'unavailable') {
  document.querySelector('#status').textContent = 'OverCrow services are not connected.';
}

import overcrow from './overcrow.js';
const status = document.querySelector('#status');
try {
  status.textContent = 'Loading…';
  const response = await overcrow.fetch('https://api.warframe.market/v2/items');
  if (!response.ok) throw new Error('HTTP ' + response.status);
  const payload = await response.json();
  if (!Array.isArray(payload?.data)) throw new Error('Invalid catalog');
  status.textContent = payload.data.length + ' items available';
} catch (error) {
  status.textContent = 'Catalog unavailable. Try again.';
  console.error(error.code ?? error.message);
}

import overcrow from './overcrow.js';
const snapshot = await overcrow.game.snapshot();
const steamAppId = snapshot.selectedActive ? snapshot.steamAppId : null;
console.log(steamAppId ?? 'Steam ID unavailable');

import overcrow from './overcrow.js';
const output = document.createElement('output');
document.body.append(output);
const render = snapshot => {
  const ms = snapshot.sessionElapsedMs;
  output.textContent = typeof ms === 'number'
    ? Math.floor(ms / 60000) + ' min' : 'Session unavailable';
};
const stop = overcrow.game.onSnapshot(render);
try { render(await overcrow.game.snapshot()); }
catch { output.textContent = 'Session unavailable'; }
window.addEventListener('pagehide', stop, { once: true });

import overcrow from './overcrow.js';
const output = document.createElement('output');
document.body.append(output);
const stop = overcrow.telemetry.onSnapshot(snapshot => {
  const value = snapshot.data?.normalizedCpuPercentHundredths;
  output.textContent = value == null ? 'CPU unavailable' : `${value / 100}% CPU`;
  if (snapshot.status === 'stale') output.textContent += ' (stale)';
});
window.addEventListener('pagehide', stop, { once: true });

import overcrow from './overcrow.js';
const title = document.createElement('p');
const play = document.createElement('button');
play.textContent = 'Play / pause';
play.disabled = true;
document.body.append(title, play);
const stop = overcrow.media.onSnapshot(snapshot => {
  title.textContent = snapshot.data?.title ?? 'No track';
  if (snapshot.status === 'stale') title.textContent += ' (stale)';
  play.disabled = snapshot.status !== 'ready' || !snapshot.data?.actions.playPause;
});
play.addEventListener('click', async () => {
  try { await overcrow.media.playPause(); }
  catch (error) { title.textContent = error.code ?? 'Playback unavailable'; }
});
window.addEventListener('pagehide', stop, { once: true });

import overcrow from './overcrow.js';
const title = document.createElement('h2');
title.textContent = 'Session';
document.body.append(title);
const stop = overcrow.presentation.onSnapshot(snapshot => {
  if (snapshot.status !== 'ready') return;
  title.hidden = snapshot.data.options.showTitle === false;
});
window.addEventListener('pagehide', stop, { once: true });

import overcrow from './overcrow.js';
const content = document.createElement('main');
content.textContent = 'Ready';
content.style.cssText = 'display: inline-block; padding: 12px';
document.body.style.margin = '0';
document.body.append(content);
const observer = new ResizeObserver(() => {
  const width = Math.max(1, Math.min(4096, Math.ceil(content.offsetWidth)));
  const height = Math.max(1, Math.min(4096, Math.ceil(content.offsetHeight)));
  overcrow.presentation.reportSize({ width, height }).catch(console.error);
});
observer.observe(content);
window.addEventListener('pagehide', () => observer.disconnect(), { once: true });

